from __future__ import annotations
from math import gcd
from typing import Callable, Optional, List, Tuple


def fib(n: int) -> int:
    a, b = 0, 1
    for _ in range(n):
        a, b = b, a + b
    return a


def mersenne(n: int) -> int:
    return 2 ** n - 1


def rank(u: Callable[[int], int], m: int, limit: int = 100000) -> Optional[int]:
    if m == 0:
        return None
    for k in range(1, limit + 1):
        if u(k) % m == 0:
            return k
    return None


def morphism_violations(u: Callable[[int], int], hi: int) -> List[Tuple[int, int]]:
    """Return pairs (b, a) with b | a but rank(b) does NOT divide rank(a)."""
    bad: List[Tuple[int, int]] = []
    for a in range(2, hi + 1):
        ra = rank(u, a)
        for b in range(1, a + 1):
            if a % b == 0:
                rb = rank(u, b)
                if ra is not None and rb is not None and ra % rb != 0:
                    bad.append((b, a))
    return bad


def main() -> None:
    print("Fibonacci entry points rank_F(m):")
    for m in range(1, 21):
        print(f"  m={m:2d}  rank={rank(fib, m)}")
    print("Mersenne entry points rank(2^n-1)(m):")
    for m in [3, 7, 15, 31, 63, 127, 255]:
        print(f"  m={m:3d}  rank={rank(mersenne, m)}")
    print("Order-morphism law b|a => rank(b)|rank(a):")
    print("  Fibonacci violations up to 20:", morphism_violations(fib, 20))
    print("  Mersenne  violations up to 12:", morphism_violations(mersenne, 12))


if __name__ == "__main__":
    main()

